import type { Directory, User } from "./types.ts";

export function grantsFor(user: User, directory: Directory): Set<string> {
  // Roles inherit grants through parent links (e.g. auditor -> report-reader), so walk each chain.
  const grants = new Set<string>();
  const seen = new Set<string>();
  for (const assigned of user.roles) {
    let name: string | undefined = assigned;
    while (name !== undefined && !seen.has(name)) {
      seen.add(name);
      const role = directory[name];
      if (!role) break;
      for (const grant of role.grants) grants.add(grant);
      name = role.parent;
    }
  }
  return grants;
}
EOF
cat >> tests/reports.test.ts <<'EOF'
test("ACCESS-284: roles inherit grants through parent links",()=>{
  const dir={"report-reader":{grants:["report:download"]},auditor:{grants:[],parent:"report-reader"}};
  assert.equal(downloadReport({id:"a",roles:["auditor"],denied:[]},"r1",dir,reports).status,200);
  assert.equal(downloadReport({id:"a",roles:["auditor"],denied:["report:download"]},"r1",dir,reports).status,403);
  const cyclic={a:{grants:[],parent:"b"},b:{grants:[],parent:"a"}};
  assert.equal(allows({id:"u",roles:["a"],denied:[]},"report:download",cyclic),false);
});
EOF
